if len(value) > 0:
	stateNameList = []
	stateData = []
	for asset in value:
		if asset is not None: 
			oeeVals = asset['OEE']
			if oeeVals['modeName'] == "Production":
				 if oeeVals['stateName'] not in stateNameList:
				 	stateNameList.append(oeeVals['stateName'])
				 	stateData.append({'stateName': oeeVals['stateName'], 'count': 1, 'stateColor': oeeVals['stateColor'], 'stateTypeColor': oeeVals['stateTypeColor']})
				 else:
				 	for state in stateData:
				 		if state['stateName'] == oeeVals['stateName']:
				 			state['count'] += 1
	return stateData
else:
	return []

assetInfoList = []

assets = sorted(value['assets'], key=lambda x: x['assetInfo']['sortOrder'])	
for asset in assets: assetInfoList.append(asset['assetInfo'])

childAssets = sorted(value['childAssets'], key=lambda x: x['assetInfo']['sortOrder'])	
for assets in childAssets:
	for k, v in assets.items():
		if k == 'assetInfo': continue
		assetInfoList.append(v['assetInfo'])	

return [{"value": {"assetInfo": item}} for item in assetInfoList]

tagInfoPathList = []
for asset in value:
	tagPath = asset['value']['assetInfo']['tagPath']
	if tagPath is not None:	tagInfoPathList.append(tagPath +'/Line')

if len(tagInfoPathList) == 0: return []

return system.tag.readBlocking(tagInfoPathList)
